import html
TPL = """<!doctype html><html><head><title>Assay</title><style>body{background:#090d16;color:#e2e8f0;font:13px monospace;max-width:960px;margin:20px auto}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #1e293b;padding:6px;text-align:left}input,button{padding:8px;background:#0f172a;color:#fff;border:1px solid #334155}button{background:#10b981;color:#000}pre{background:#0f172a;padding:8px}</style></head><body><h2>Assay — A2A Observatory</h2><div style='display:flex;gap:8px'><input id='u' placeholder='https://endpoint.com' style='flex:1'><button onclick='pf()'>Pre-Flight</button><button onclick='buy()'>Pass ($19)</button></div><pre id='o'>MCP: POST /mcp | JSON: GET /v1/leaderboard</pre><table><tr><th>Endpoint</th><th>Grade</th><th>Conf</th><th>Tools</th><th>Hash</th><th>Rugs</th><th>Ms</th><th>Badge</th></tr>__TR__</table><script>async function pf(){const r=await fetch('/v1/preflight',{method:'POST',body:JSON.stringify({target:u.value})});o.textContent=JSON.stringify(await r.json(),null,2)}async function buy(){const r=await fetch('/v1/billing/stripe-checkout',{method:'POST',body:'{}'});const d=await r.json();if(d.checkout_url)location.href=d.checkout_url}const q=new URLSearchParams(location.search).get('inspect');if(q){u.value=q;pf()}</script></body></html>"""
def render_home(rows):
  e = html.escape
  return TPL.replace("__TR__", "".join(f"<tr><td><a href='{e(r['target'])}'>{e(r['name'][:22])}</a></td><td>{r['grade']}({r['score']})</td><td>{r['confidence']}({r['probes']})</td><td>{r['mcp_tools']}</td><td>{(r['tools_hash'] or '-')[:8]}</td><td>{r['rug_pulls']}</td><td>{r['latency_ms']}</td><td><img src='/v1/badge.svg?target={e(r['target'])}'/></td></tr>" for r in rows))
